static IEnumerable<long> Fibonacci() {
    for (long a = 0, b = 1; ; (a, b) = (b, a + b))
        yield return a;                     // resumed per MoveNext
}

var firstEven = Fibonacci().Where(n => n % 2 == 0).First();   // forces 3 elements

