async IAsyncEnumerable<Order> Page([EnumeratorCancellation] CancellationToken ct) {
    string? cursor = null;
    do {
        var page = await _api.GetOrders(cursor, ct);
        foreach (var o in page.Items) yield return o;   // awaited per page
        cursor = page.Next;
    } while (cursor is not null);
}
